{
  "description": "Put a new event on the calendar at a given date and time.",
  "destructive": true,
  "parameters": {
    "type": "object",
    "properties": {
      "title": {
        "type": "string",
        "description": "What the event is called."
      },
      "date": {
        "type": "string",
        "description": "The date, as YYYY-MM-DD."
      },
      "start_time": {
        "type": "string",
        "description": "Start time in 24-hour HH:MM, local."
      },
      "duration_minutes": {
        "type": "integer",
        "description": "How long, in minutes. Defaults to 30."
      }
    },
    "required": [
      "title",
      "date",
      "start_time"
    ]
  }
}

parameters.jsCode:
const b = $input.first().json.body || {};
const dm = String(b.date || '').match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
const tm = String(b.start_time || '').match(/^(\d{1,2}):(\d{2})$/);
if (!dm || !tm) throw new Error('date must be YYYY-MM-DD and start_time must be HH:MM');

const mins = Number(b.duration_minutes || 30);
const start = new Date(+dm[1], +dm[2]-1, +dm[3], +tm[1], +tm[2], 0, 0);
const end = new Date(start.getTime() + mins * 60000);
return [{ json: { title: String(b.title || 'Untitled'),
                  start: start.toISOString(), end: end.toISOString(),
                  human: start.toLocaleString('en-GB',{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}),
                  minutes: mins } }];

const meta = $('Prepare').first().json;
const ev = $input.first().json || {};
return [{ json: { created: !!ev.id, title: meta.title, when: meta.human,
                  minutes: meta.minutes, link: ev.htmlLink || null } }];
